<?php declare(strict_types=1); require_once __DIR__.'/includes/bootstrap.php'; require_once __DIR__.'/includes/ensure_courses.php'; $lh_page_title='Courses'; $lh_description='Practical SmartToolz courses for computer skills, web development, programming, AI, design, SEO and career skills.'; $rows=[]; try{$rows=$db->query("SELECT c.*,lc.name category_name,lc.icon category_icon,(SELECT COUNT(*) FROM learning_lessons l WHERE l.course_id=c.id AND l.enabled=1) lesson_count FROM learning_courses c LEFT JOIN learning_categories lc ON lc.id=c.category_id WHERE c.enabled=1 ORDER BY c.featured DESC,c.id DESC")->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){error_log($e->getMessage());} $category=trim((string)($_GET['category']??'')); if($category!==''){$rows=array_values(array_filter($rows,fn($r)=>($r['category_name']??'')===$category));} include __DIR__.'/includes/header.php'; include __DIR__.'/includes/navbar.php'; ?><div class="container-fluid"><div class="row"><div class="col-lg-3 col-xl-2 p-0"><?php include __DIR__.'/includes/sidebar.php'; ?></div><main class="col-lg-9 col-xl-10 py-4 py-lg-5"><div class="container-fluid"><div class="mb-4"><h1 class="fw-bold">Courses</h1><p class="text-secondary">Choose a practical learning path and start building.</p></div><div class="row g-3"><?php foreach($rows as $c): ?><div class="col-md-6 col-xl-4"><a class="lh-card d-flex flex-column h-100 p-4" href="/learning-hub/course.php?slug=<?=rawurlencode($c['slug'])?>"><div class="fs-2"><?=lh_h($c['category_icon']??'📚')?></div><h2 class="h5 mt-3 mb-2"><?=lh_h($c['title'])?></h2><p class="small text-secondary"><?=lh_h($c['description']??'')?></p><div class="mt-auto pt-3 d-flex justify-content-between small fw-semibold"><span><?=lh_h($c['level'])?></span><span><?=number_format((int)$c['lesson_count'])?> lessons</span></div></a></div><?php endforeach;if(!$rows): ?><div class="col-12"><div class="alert alert-light border">Courses are being prepared. Please refresh shortly.</div></div><?php endif; ?></div><div class="lh-ad-slot my-5">Advertisement</div></div></main></div></div><?php include __DIR__.'/includes/footer.php'; ?><script src="/learning-hub/assets/js/app.js"></script>